package com.sigtm.backend.service;
import com.sigtm.backend.exception.ResourceNotFoundException; import com.sigtm.backend.model.*; import com.sigtm.backend.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.Set;
@Service @RequiredArgsConstructor public class SeguimientoCompraService {private final SeguimientoCompraRepository tracking;private final OrdenCompraRepository orders;private final AuditoriaService audit;
 @Transactional public SeguimientoCompra actualizar(Long orderId,SeguimientoCompra data){OrdenCompra o=orders.findDetailedById(orderId).orElseThrow(()->new ResourceNotFoundException("Orden no encontrada"));if(!Set.of("ENVIADA","EN_TRANSITO","ENTREGADA","DEMORADA").contains(data.getStatus()))throw new IllegalArgumentException("Estado logístico inválido");SeguimientoCompra s=tracking.findByPurchaseOrderId(orderId).orElse(SeguimientoCompra.builder().purchaseOrder(o).build());s.setStatus(data.getStatus());s.setDispatchedAt(data.getDispatchedAt());s.setEstimatedArrival(data.getEstimatedArrival());s.setActualArrival(data.getActualArrival());s.setShippingGuide(data.getShippingGuide());s.setCarrier(data.getCarrier());s.setNotes(data.getNotes());s=tracking.save(s);audit.registrar("UPDATE","SEGUIMIENTO_COMPRA",s.getId(),"Seguimiento "+o.getCode()+": "+s.getStatus());return s;}
 @Transactional(readOnly=true) public SeguimientoCompra obtener(Long orderId){return tracking.findByPurchaseOrderId(orderId).orElseThrow(()->new ResourceNotFoundException("Seguimiento no encontrado"));}}
